class CustomerFilterTest {

    private static final Customer ADA = new Customer(
            1L, "Ada", "Aaltonen", "ada@example.com", "Finland", CustomerStatus.ACTIVE);
    private static final Customer JOSEPHINE = new Customer(
            2L, "Joséphine", "Mäkinen", "josephine@example.com", "France", CustomerStatus.CLOSED);

    private static boolean matches(CustomerFilter filter, Customer customer) {
        return filter.asPredicate().test(customer);
    }

    @Test
    void allMatchesEveryCustomer() {
        assertTrue(matches(CustomerFilter.ALL, ADA));
        assertTrue(matches(CustomerFilter.ALL, JOSEPHINE));
    }

    @Test
    void blankNameMatchesEveryone() {
        assertTrue(matches(new CustomerFilter("   ", Set.of()), ADA));
    }

    @Test
    void everyTermMustAppearInFirstOrLastName() {
        assertTrue(matches(new CustomerFilter("ada aal", Set.of()), ADA));
        assertTrue(matches(new CustomerFilter("aal ada", Set.of()), ADA));
        assertFalse(matches(new CustomerFilter("ada mak", Set.of()), ADA));
    }

    @Test
    void termsMayComeFromDifferentNameParts() {
        // "ada" from the first name, "aal" from the last name.
        assertTrue(matches(new CustomerFilter("  ada   aal ", Set.of()), ADA));
    }

    @Test
    void nameMatchingIgnoresCase() {
        assertTrue(matches(new CustomerFilter("ADA", Set.of()), ADA));
    }

    @Test
    void nameMatchingIgnoresAccentsInBothDirections() {
        assertTrue(matches(new CustomerFilter("makinen", Set.of()), JOSEPHINE));
        assertTrue(matches(new CustomerFilter("MÄKINEN", Set.of()), JOSEPHINE));
        assertTrue(matches(new CustomerFilter("josephine", Set.of()), JOSEPHINE));
        assertTrue(matches(new CustomerFilter("Joséphine", Set.of()), JOSEPHINE));
    }

    @Test
    void emptyStatusSetMatchesEveryStatus() {
        assertTrue(matches(new CustomerFilter("", Set.of()), ADA));
        assertTrue(matches(new CustomerFilter("", Set.of()), JOSEPHINE));
    }

    @Test
    void statusSetKeepsOnlyListedStatuses() {
        CustomerFilter activeOnly = new CustomerFilter("", Set.of(CustomerStatus.ACTIVE));
        assertTrue(matches(activeOnly, ADA));
        assertFalse(matches(activeOnly, JOSEPHINE));
    }

    @Test
    void nameAndStatusMustBothMatch() {
        CustomerFilter filter = new CustomerFilter("makinen", Set.of(CustomerStatus.ACTIVE));
        assertFalse(matches(filter, JOSEPHINE));
    }
}
