+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.List;
+import java.util.Locale;
+import java.util.Objects;
+import java.util.Set;
+import java.util.function.Predicate;
+import java.util.regex.Pattern;
+
+/**
+ * Narrows the customer list. A customer must satisfy both parts.
+ *
+ * @param name     text the customer's first or last name must contain. It is split on
+ *                 whitespace, and every term must appear in the first name or the last
+ *                 name. Case and accents are ignored. Blank matches every name.
+ * @param statuses the statuses a customer may have. Empty matches every status.
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    /** Matches every customer. */
+    public static final CustomerFilter ALL = new CustomerFilter("", Set.of());
+
+    private static final Pattern WHITESPACE = Pattern.compile("[\\s\\p{Z}]+");
+    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        name = Objects.requireNonNullElse(name, "");
+        statuses = Set.copyOf(statuses);
+    }
+
+    /**
+     * Returns a test for this filter. The name is split into terms once, here, rather
+     * than once per customer.
+     */
+    public Predicate<Customer> asPredicate() {
+        List<String> terms = terms(name);
+        return customer -> (statuses.isEmpty() || statuses.contains(customer.status()))
+                && matchesEveryTerm(terms, customer);
+    }
+
+    private static boolean matchesEveryTerm(List<String> terms, Customer customer) {
+        String firstName = fold(customer.firstName());
+        String lastName = fold(customer.lastName());
+        return terms.stream()
+                .allMatch(term -> firstName.contains(term) || lastName.contains(term));
+    }
+
+    private static List<String> terms(String text) {
+        return WHITESPACE.splitAsStream(fold(text))
+                .filter(term -> !term.isEmpty())
+                .toList();
+    }
+
+    /** Lower-cases the text and strips accents, so {@code Mäkinen} folds to {@code makinen}. */
+    private static String fold(String text) {
+        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
+        return COMBINING_MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
